def adjustHeart(value)
  return if !shadowPokemon?
  @heart_gauge = (self.heart_gauge + value).clamp(0, max_gauge_size)
end

def add_evs(added_evs)
  total = 0
  @ev.each_value { |e| total += e }
  GameData::Stat.each_main do |s|
    addition = added_evs[s.id].clamp(0, Pokemon::EV_STAT_LIMIT - @ev[s.id])
    addition = addition.clamp(0, Pokemon::EV_LIMIT - total)
    next if addition == 0
    @ev[s.id] += addition
    total += addition
  end
end

def initialize(hash)
  @id              = hash[:id]
  @species         = hash[:species]         || @id
  @form            = hash[:form]            || 0
  @gauge_size      = hash[:gauge_size]      || HEART_GAUGE_SIZE
  @moves           = hash[:moves]           || []
  @flags           = hash[:flags]           || []
  @pbs_file_suffix = hash[:pbs_file_suffix] || ""
end

def partialSum(x)
  return ((x * x) + x) / 2   # pattern: 1, 3, 6, 10, 15, 21, 28, ...
end

def isPurifiable?(set)
  isPurifiableIgnoreRegular?(set) && setCount(set) > 0
end
